-- City photos: each city's lead photo from Wikipedia, served by Wikimedia
-- Commons. They are freely licensed and most require attribution, so the
-- author, licence and source page are stored with them and shown wherever the
-- photo is.

alter table public.cities
  add column photo_url text check (photo_url ~ '^https://'),
  add column photo_thumb_url text check (photo_thumb_url ~ '^https://'),
  add column photo_author text check (char_length(photo_author) <= 160),
  add column photo_license text check (char_length(photo_license) <= 40),
  add column photo_license_url text check (photo_license_url ~ '^https?://'),
  add column photo_source_url text check (photo_source_url ~ '^https://'),
  add constraint cities_photo_credited check (photo_url is null or (photo_author is not null and photo_license is not null and photo_source_url is not null));

update public.cities c set
  photo_url = v.photo_url,
  photo_thumb_url = v.photo_thumb_url,
  photo_author = v.photo_author,
  photo_license = v.photo_license,
  photo_license_url = v.photo_license_url,
  photo_source_url = v.photo_source_url
